import{_ as r,o as i,c as a,ah as t}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Recherche: Das Ibiza-Video (Die Mutter aller Enthüllungen)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/ibiza-video.md","filePath":"recherche/ibiza-video.md"}'),n={name:"recherche/ibiza-video.md"};function s(d,e,l,o,h,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="recherche-das-ibiza-video-die-mutter-aller-enthullungen" tabindex="-1">Recherche: Das Ibiza-Video (Die Mutter aller Enthüllungen) <a class="header-anchor" href="#recherche-das-ibiza-video-die-mutter-aller-enthullungen" aria-label="Permalink to &quot;Recherche: Das Ibiza-Video (Die Mutter aller Enthüllungen)&quot;">​</a></h1><p>Obwohl dieses Video primär die FPÖ-Führung (Strache/Gudenus) zu Fall brachte, ist es für unsere Mockumentary der unverzichtbare Prolog zur Schredder-Affäre und zum &quot;System Kurz&quot;.</p><h2 id="die-szene" tabindex="-1">Die Szene <a class="header-anchor" href="#die-szene" aria-label="Permalink to &quot;Die Szene&quot;">​</a></h2><p>Ein Sofa, Wodka-Red-Bull, eine angebliche russische Oligarchin und das Versprechen, Österreichs Staatsaufträge wie auf einem Basar zu verteilen. Es ist die filmreife Darstellung dessen, was passiert, wenn politische Gier auf versteckte Kameras trifft.</p><h2 id="die-relevanz" tabindex="-1">Die Relevanz <a class="header-anchor" href="#die-relevanz" aria-label="Permalink to &quot;Die Relevanz&quot;">​</a></h2><p>Das Ibiza-Video öffnete die &quot;Büchse der Pandora&quot;. Ohne die Ermittlungen nach Ibiza hätte es nie die Sicherstellung der Thomas-Schmid-Chats gegeben – und damit niemals den tiefen Einblick in die Postenschacher- und Inseraten-Affären der ÖVP.</p><h3 id="links-medien" tabindex="-1">Links &amp; Medien: <a class="header-anchor" href="#links-medien" aria-label="Permalink to &quot;Links &amp; Medien:&quot;">​</a></h3><ul><li><strong>Der Film zum Video:</strong> <a href="https://de.wikipedia.org/wiki/Ibiza-Aff%C3%A4re" target="_blank" rel="noreferrer">Wikipedia: Ibiza-Affäre</a></li><li><strong>Die Chats:</strong> Das System der &quot;Message Control&quot; und die Folgen für die Demokratie.</li><li><strong>Video-Ausschnitte:</strong> <a href="https://www.youtube.com/results?search_query=ibiza+video+strache" target="_blank" rel="noreferrer">YouTube-Suche: Ibiza Video Strache</a></li></ul><hr><p><em>In unserer Mockumentary nutzen wir die &#39;Ibiza-Logik&#39; als Metapher für die Hinterzimmer-Gespräche der 30er Jahre.</em></p>',10)])])}const f=r(n,[["render",s]]);export{m as __pageData,f as default};
